from __future__ import annotations

import pandas as pd
import plotly.express as px
import streamlit as st

from analytics.mongo_aggregations import events_by_category, top_source_ips
from detection.ml_network import DEFAULT_MODEL_PATH, load_model_bundle
from ui.resources import get_mongo, mysql_rows
from ui.theme import configure_page

configure_page("Threat Analytics", "📊")
st.info(
    "Dataset attack categories are source-provided labels. They are shown separately "
    "from alerts generated by authentication rules and the trained network model."
)

bundle = load_model_bundle(str(DEFAULT_MODEL_PATH.resolve()))
metrics = bundle["metadata"]["test_metrics"]
baseline = bundle["metadata"]["rule_baseline_on_same_test_split"]
metric_columns = st.columns(5)
metric_columns[0].metric("Model recall", f"{metrics['recall']:.1%}")
metric_columns[1].metric("Model precision", f"{metrics['precision']:.1%}")
metric_columns[2].metric("Model F1", f"{metrics['f1']:.1%}")
metric_columns[3].metric("False negatives", metrics["false_negatives"])
metric_columns[4].metric("False positives", metrics["false_positives"])
st.caption(
    f"Same held-out split: the original rule detector recall was {baseline['recall']:.1%} "
    f"with {baseline['false_negatives']} false negatives. These are quickstart evaluation "
    "results, not live-traffic guarantees."
)

mongo = get_mongo().database
categories = pd.DataFrame(list(mongo.security_events.aggregate(events_by_category())))
if not categories.empty:
    categories = categories.rename(columns={"_id": "observed_category"})
    st.plotly_chart(
        px.bar(categories, x="observed_category", y="event_count",
               title="Observed dataset categories"),
        width="stretch",
    )

left, right = st.columns(2)
sources = pd.DataFrame(list(mongo.security_events.aggregate(top_source_ips(15))))
if not sources.empty:
    sources = sources.rename(columns={"_id": "source_ip"})
    left.dataframe(sources, width="stretch", hide_index=True)

rules = pd.DataFrame(
    mysql_rows(
        """
        SELECT detected_by AS rule_name, severity, COUNT(*) incident_count
        FROM incidents GROUP BY detected_by, severity ORDER BY incident_count DESC
        """
    )
)
if not rules.empty:
    right.plotly_chart(
        px.bar(rules, x="rule_name", y="incident_count", color="severity",
               title="Rule/model-generated incidents"),
        width="stretch",
    )
